xhtml:div.xhtml:script:

const TARGET_URL = "https://pizzaedition.win";

document.getElementById('launchBtn').addEventListener('click', function launchGame() {
  const url = TARGET_URL.trim();
  if (!url) {
    alert('Please set the TARGET_URL in the script.');
    return;
  }
  const win = window.open('about:blank', '_blank');
  if (!win) {
    alert("Pop-up blocked! Please allow pop-ups.");
    return;
  }

  // Disguise tab as Google Docs
  win.document.title = "Google Docs - Shared";
  const icon = win.document.createElement('link');
  icon.rel = 'icon';
  icon.href = 'https://gstatic.com/favicon.ico';
  win.document.head.appendChild(icon);

  // Create iframe filling the entire tab
  const iframe = win.document.createElement('iframe');
  iframe.src = url;
  iframe.style.cssText = `
    position: fixed; top: 0; left: 0; width: 100%; height: 100%; border: none; background: #000; z-index: 9999;
  `;

  // Permissions for iframe
  iframe.setAttribute('allow', 'fullscreen; pointer-lock; camera; microphone; autoplay');
  iframe.setAttribute('sandbox', 'allow-scripts allow-same-origin allow-forms allow-popups allow-moderation');

  // Append iframe
  win.document.body.style.margin = '0';
  win.document.body.appendChild(iframe);

  // Hotkey to escape
  win.addEventListener('keydown', function(e) {
    if (e.key === '`') {
      win.location.replace('https://classroom.google.com');
    }
  });
});
